public class MyTask implements Runnable {
    @Override
    public void run() {
        for (int i = 1; i <= 5; i++) {
            System.out.println("Worker Thread: " + i);
            try { Thread.sleep(500); } catch (Exception e) {}
        }
    }
}

public static void main(String[] args) {
    MyTask task = new MyTask();
    Thread secondWorker = new Thread(task);

    secondWorker.start(); // This runs simultaneously!

    for (int i = 1; i <= 5; i++) {
        System.out.println("Main Thread: " + i);
        try { Thread.sleep(500); } catch (Exception e) {}
    }
}

import java.util.Scanner;

public class AlarmClock {
    private final Scanner scanner;

    // Constructor: We receive the scanner from the Main method
    public AlarmClock(Scanner scanner) {
        this.scanner = scanner;
    }

    public void startAlarm() {
        // Imagine code here that loops and checks the time...
        System.out.println("[Music Playing!]");

        // The alarm is ringing! Wait for the user to turn it off.
        System.out.println("Press Enter to stop the alarm.");
        scanner.nextLine();

        System.out.println("Alarm stopped.");
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner mainScanner = new Scanner(System.in);

        // Instantiate our custom Object
        AlarmClock myClock = new AlarmClock(mainScanner);

        System.out.println("Alarm set for 8:07 AM");
